import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

__device__ __forceinline__ float fast_tanh(float x) {
    float r;
    asm("tanh.approx.f32 %0, %1;" : "=f"(r) : "f"(x));
    return r;
}
__global__ void tanh_kernel_vec4(const float4* __restrict__ in, float4* __restrict__ out, int64_t n4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    #pragma unroll 4
    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = __ldg(&in[i]);
        float4 r;
        r.x = fast_tanh(v.x);
        r.y = fast_tanh(v.y);
        r.z = fast_tanh(v.z);
        r.w = fast_tanh(v.w);
        out[i] = r;
    }
}
__global__ void tanh_kernel_scalar(const float* __restrict__ in, float* __restrict__ out, int64_t n) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    #pragma unroll 4
    for (int64_t i = idx; i < n; i += stride) {
        out[i] = fast_tanh(__ldg(&in[i]));
    }
}
torch::Tensor tanh_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int64_t n = x_contig.numel();
    bool can_vec4 = (n % 4 == 0) &&
        (reinterpret_cast<uintptr_t>(x_contig.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(out.data_ptr<float>()) % 16 == 0);
    const int blockSize = 256;
    const int64_t maxBlocks = 65536;
    if (can_vec4) {
        int64_t n4 = n / 4;
        int64_t neededBlocks = (n4 + blockSize - 1) / blockSize;
        int blocks = (int)std::min<int64_t>(neededBlocks, maxBlocks);
        if (blocks < 1) blocks = 1;
        tanh_kernel_vec4<<<blocks, blockSize>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            n4
        );
    } else {
        int64_t neededBlocks = (n + blockSize - 1) / blockSize;
        int blocks = (int)std::min<int64_t>(neededBlocks, maxBlocks);
        if (blocks < 1) blocks = 1;
        tanh_kernel_scalar<<<blocks, blockSize>>>(
            x_contig.data_ptr<float>(),
            out.data_ptr<float>(),
            n
        );
    }
    return out;
}
"""
cpp_source = r"""
torch::Tensor tanh_cuda(torch::Tensor x);
"""
_tanh_ext = load_inline(
    name="fast_tanh_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["tanh_cuda"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._op = _tanh_ext
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._op.tanh_cuda(x)

